import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  sheetCloseClassName,
  sheetContentClassName,
  sheetDescriptionClassName,
  sheetFooterClassName,
  sheetHeaderClassName,
  sheetOverlayClassName,
  sheetPortalClassName,
  sheetRootClassName,
  sheetTitleClassName,
  sheetTriggerClassName,
} from "./view";

export {
  sheetCloseClassName,
  sheetContentClassName,
  sheetDescriptionClassName,
  sheetFooterClassName,
  sheetHeaderClassName,
  sheetOverlayClassName,
  sheetPortalClassName,
  sheetRootClassName,
  sheetTitleClassName,
  sheetTriggerClassName,
} from "./view";

export type ViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = ViewConfig &
  Readonly<{ onOpen: ParentMessage }>;

export type PortalViewConfig = ViewConfig & Readonly<{ open: boolean }>;

export type ContentViewConfig = ViewConfig &
  Readonly<{
    ariaDescribedBy?: string | undefined;
    ariaLabelledBy?: string | undefined;
  }>;

export type LabelViewConfig = Readonly<{
  id?: string | undefined;
  label: string;
}>;

export type CloseViewConfig<ParentMessage> = ViewConfig &
  Readonly<{ onClose: ParentMessage; ariaLabel?: string | undefined }>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sheet"),
      h.Class(classNames(sheetRootClassName, className)),
    ],
    children
  );
};

export const triggerView = <ParentMessage>({
  children,
  onOpen,
  className,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.OnClick(onOpen),
      h.DataAttribute("slot", "sheet-trigger"),
      h.Class(classNames(sheetTriggerClassName, className)),
    ],
    children
  );
};

export const portalView = <ParentMessage>({
  open,
  children,
  className,
}: PortalViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.empty;
  }

  return h.div(
    [
      h.DataAttribute("slot", "sheet-portal"),
      h.Class(classNames(sheetPortalClassName, className)),
    ],
    children
  );
};

export const overlayView = <ParentMessage>({
  children = [],
  className,
}: Partial<ViewConfig>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sheet-overlay"),
      h.Class(classNames(sheetOverlayClassName, className)),
    ],
    children
  );
};

export const contentView = <ParentMessage>({
  children,
  className,
  ariaDescribedBy,
  ariaLabelledBy,
}: ContentViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "dialog"),
      h.AriaModal(true),
      ...(ariaLabelledBy === undefined
        ? []
        : [h.AriaLabelledBy(ariaLabelledBy)]),
      ...(ariaDescribedBy === undefined
        ? []
        : [h.AriaDescribedBy(ariaDescribedBy)]),
      h.DataAttribute("slot", "sheet-content"),
      h.Class(classNames(sheetContentClassName, className)),
    ],
    children
  );
};

export const headerView = <ParentMessage>({
  children,
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sheet-header"),
      h.Class(classNames(sheetHeaderClassName, className)),
    ],
    children
  );
};

export const titleView = <ParentMessage>({
  id,
  label,
}: LabelViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.h2(
    [
      ...(id === undefined ? [] : [h.Id(id)]),
      h.DataAttribute("slot", "sheet-title"),
      h.Class(sheetTitleClassName),
    ],
    [label]
  );
};

export const descriptionView = <ParentMessage>({
  id,
  label,
}: LabelViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.p(
    [
      ...(id === undefined ? [] : [h.Id(id)]),
      h.DataAttribute("slot", "sheet-description"),
      h.Class(sheetDescriptionClassName),
    ],
    [label]
  );
};

export const closeView = <ParentMessage>({
  children,
  onClose,
  ariaLabel = "Close sheet",
  className,
}: CloseViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.AriaLabel(ariaLabel),
      h.OnClick(onClose),
      h.DataAttribute("slot", "sheet-close"),
      h.Class(classNames(sheetCloseClassName, className)),
    ],
    children
  );
};

export const footerView = <ParentMessage>({
  children,
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "sheet-footer"),
      h.Class(classNames(sheetFooterClassName, className)),
    ],
    children
  );
};

export const sheetRootClassName = "relative";
export const sheetTriggerClassName =
  "inline-flex items-center justify-center rounded-md bg-gray-950 px-4 py-2 text-sm font-medium text-white shadow-sm transition hover:bg-gray-800 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";
export const sheetPortalClassName = "fixed inset-0 z-50";
export const sheetOverlayClassName = "fixed inset-0 bg-black/45";
export const sheetContentClassName =
  "fixed right-0 top-0 z-50 flex h-full w-full max-w-sm flex-col gap-4 border-l border-gray-200 bg-white p-6 shadow-xl";
export const sheetHeaderClassName = "grid gap-1.5 text-left";
export const sheetTitleClassName = "text-lg font-semibold text-gray-950";
export const sheetDescriptionClassName = "text-sm text-gray-600";
export const sheetCloseClassName =
  "absolute right-4 top-4 rounded-sm p-1 text-gray-500 opacity-70 transition hover:opacity-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";
export const sheetFooterClassName =
  "mt-auto flex flex-col-reverse gap-2 sm:flex-row sm:justify-end";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Sheet from "./index";

const view = (open: boolean): Html => {
  const h = html<string>();

  return Sheet.rootView<string>({
    children: [
      Sheet.triggerView<string>({
        onOpen: "open",
        children: [h.span([], ["Open"])],
      }),
      Sheet.portalView<string>({
        open,
        children: [
          Sheet.overlayView<string>({}),
          Sheet.contentView<string>({
            ariaDescribedBy: "sheet-description",
            ariaLabelledBy: "sheet-title",
            children: [
              Sheet.headerView<string>({
                children: [
                  Sheet.titleView<string>({
                    id: "sheet-title",
                    label: "Edit profile",
                  }),
                  Sheet.descriptionView<string>({
                    id: "sheet-description",
                    label: "Make changes to your profile.",
                  }),
                ],
              }),
              Sheet.closeView<string>({
                onClose: "close",
                children: [h.span([], ["x"])],
              }),
            ],
          }),
        ],
      }),
    ],
  });
};

describe("Sheet registry view", () => {
  test("renders controlled dialog content", () => {
    Scene.scene(
      {
        update: (model: boolean): readonly [boolean, []] => [model, []],
        view,
      },
      Scene.with(true),
      Scene.expect(Scene.role("dialog")).toHaveAttr("aria-modal", "true"),
      Scene.expect(Scene.role("dialog")).toHaveAttr(
        "aria-labelledby",
        "sheet-title"
      ),
      Scene.expect(Scene.role("dialog")).toHaveAttr(
        "aria-describedby",
        "sheet-description"
      ),
      Scene.expect(Scene.text("Edit profile")).toExist(),
      Scene.expect(Scene.role("button", { name: "Close sheet" })).toExist()
    );
  });
});
